// Shapes as they are edited in the spreadsheet editor: inserted from the menu of the toolbar,
// drawn, selected, moved and sized with the pointer, turned by the handle above the frame, moved
// with the arrows and deleted with Delete; filled and outlined from the toolbar; given text in a
// field over the shape (a double click, Enter); copied and pasted; saved and read again; refused
// in a read-only view and on a sheet whose objects are protected.
//
// No screenshots: the pixels of the canvas are read with getImageData(). Every workbook is
// generated by code. Columns are 64 pixels wide and rows 20 high; the header is 72 by 22.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { pictureWorkbook } from '../test/picture-fixtures';
import { outline, sp, twoCell } from '../test/sheet-drawing-fixtures';
import { expect, test } from './helpers';

const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;
const EMU = 9525;
const MOUSE_ONLY = 'a mouse is needed';
/** The fill a rectangle starts with (#4472C4), and one the tests give it (#FF0000). */
const ACCENT = [0x44, 0x72, 0xc4];
const RED = [255, 0, 0];

const plainBook = () => buildXlsx({ sheets: [{ name: 'Sayfa1', xml: worksheetXml('<sheetData><row r="1"><c r="A1"><v>1</v></c></row></sheetData>') }] });

async function mount(page: Page, bytes: Uint8Array | number[], options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes as Uint8Array).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('#host .bym-canvas')).toBeVisible();
}

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', 'api', `return ${code}`)((window as any).__editor.view, (window as any).BymOffice), code);
const shapes = (page: Page): Promise<any[]> => view(page, 'view.shapes()') as Promise<any[]>;
const live = (page: Page) => page.locator('#host .bym-live');
const command = (page: Page, name: string) => page.locator(`#host .bym-toolbar [data-command="${name}"]`);
const popover = (page: Page) => page.locator('#host .bym-popover');
const saved = (page: Page) => page.evaluate(async () => Array.from((await (window as any).__file.save()) as Uint8Array));

/** How many pixels of a colour a box of the canvas (CSS pixels) holds, after a forced redraw. */
function ink(page: Page, colour: number[], box: { x: number; y: number; width: number; height: number }): Promise<number> {
  return page.evaluate(
    ([colour, box]) => {
      const view = (window as any).__editor.view;
      view.render();
      const canvas = document.querySelector('#host .bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      const area = box as { x: number; y: number; width: number; height: number };
      const width = Math.max(1, Math.round(area.width * dpr));
      const height = Math.max(1, Math.round(area.height * dpr));
      const data = canvas.getContext('2d')!.getImageData(Math.round(area.x * dpr), Math.round(area.y * dpr), width, height).data;
      const [r, g, b] = colour as number[];
      let count = 0;
      for (let at = 0; at < data.length; at += 4) if (Math.abs(data[at] - r) <= 6 && Math.abs(data[at + 1] - g) <= 6 && Math.abs(data[at + 2] - b) <= 6) count++;
      return count / (dpr * dpr);
    },
    [colour, box] as [number[], typeof box],
  );
}

/** The box of a shape on the canvas, CSS pixels, as its anchor says (no scrolling, no frozen panes). */
async function frameOf(page: Page, id = 0): Promise<{ x: number; y: number; width: number; height: number }> {
  const anchor = (await shapes(page)).find((shape) => shape.id === id).anchor;
  const x = (marker: any) => HEADER_WIDTH + marker.col * COLUMN_WIDTH + marker.colOff / EMU;
  const y = (marker: any) => HEADER_HEIGHT + marker.row * ROW_HEIGHT + marker.rowOff / EMU;
  if (anchor.kind === 'twoCell') return { x: x(anchor.from), y: y(anchor.from), width: x(anchor.to) - x(anchor.from), height: y(anchor.to) - y(anchor.from) };
  if (anchor.kind === 'oneCell') return { x: x(anchor.from), y: y(anchor.from), width: anchor.width / EMU, height: anchor.height / EMU };
  return { x: HEADER_WIDTH + anchor.x / EMU, y: HEADER_HEIGHT + anchor.y / EMU, width: anchor.width / EMU, height: anchor.height / EMU };
}

async function canvasBox(page: Page): Promise<{ x: number; y: number }> {
  const box = await page.locator('#host .bym-canvas').boundingBox();
  if (!box) throw new Error('the canvas has no box');
  return box;
}

function key(page: Page, init: KeyboardEventInit): Promise<boolean> {
  return page.evaluate((init) => {
    const event = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, ...init });
    document.querySelector('#host .bym-input')!.dispatchEvent(event);
    return event.defaultPrevented;
  }, init);
}

/** A clipboard event in the grid of the editor: what the view put on the clipboard (copy, cut), or what it is given to paste. */
function clipboard(page: Page, type: 'copy' | 'cut' | 'paste', give?: { text: string; html: string }): Promise<{ text: string; html: string }> {
  return page.evaluate(
    ([type, text, html]) => {
      const data = new DataTransfer();
      if (text !== null) data.setData('text/plain', text);
      if (html !== null) data.setData('text/html', html);
      let event: Event | undefined;
      try {
        event = new ClipboardEvent(type as string, { clipboardData: data, bubbles: true, cancelable: true });
      } catch {
        event = undefined;
      }
      // Some browsers give a scripted clipboard event a clipboard of their own instead of the one passed in.
      if (!event || (event as ClipboardEvent).clipboardData !== data) {
        event = new Event(type as string, { bubbles: true, cancelable: true });
        Object.defineProperty(event, 'clipboardData', { value: data });
      }
      document.querySelector('#host .bym-input')!.dispatchEvent(event);
      return { text: data.getData('text/plain'), html: data.getData('text/html') };
    },
    [type, give ? give.text : null, give ? give.html : null] as [string, string | null, string | null],
  );
}

test.describe('shapes are edited', () => {
  test('the menu of the toolbar inserts each kind at the active cell; a rectangle is drawn, selected, saved and read again', async ({ page }) => {
    await mount(page, await plainBook());
    await view(page, 'view.select(api.parseRange("B2"))');
    await command(page, 'insertShape').click();
    await expect(popover(page)).toBeVisible();
    const items = await popover(page).locator('.bym-pop-item').allTextContents();
    expect(items).toEqual(['Rectangle', 'Rounded rectangle', 'Oval', 'Line', 'Arrow', 'Double arrow', 'Text box']);
    await popover(page).locator('.bym-pop-item').first().click();
    await expect(live(page)).toHaveText('Shape inserted');
    expect(await view(page, 'view.selectedShape')).toBe(0);
    const list = await shapes(page);
    expect([list[0].geometry, list[0].anchor.kind, list[0].anchor.from, list[0].ofFile, list[0].formattable]).toEqual(['rect', 'twoCell', { col: 1, colOff: 0, row: 1, rowOff: 0 }, false, true]);
    const frame = await frameOf(page);
    expect([Math.round(frame.width), Math.round(frame.height)]).toEqual([160, 80]);
    expect(await ink(page, ACCENT, { x: frame.x + 6, y: frame.y + 6, width: frame.width - 12, height: frame.height - 12 })).toBeGreaterThan(0.9 * (frame.width - 12) * (frame.height - 12));
    const bytes = await saved(page);
    await mount(page, bytes);
    const again = await shapes(page);
    expect([again.length, again[0].ofFile, again[0].formattable, again[0].fill]).toEqual([1, true, true, '#4472C4']);
  });

  test('a shape is selected by a click, moved by a drag, sized by its corner and turned by the handle above it; each is one undo step', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await plainBook());
    await view(page, 'view.insertShape("rect", { at: { row: 2, col: 1 } })');
    await view(page, 'view.selectShape(undefined)');
    const canvas = await canvasBox(page);
    const start = await frameOf(page);
    let frame = start;
    await page.mouse.click(canvas.x + frame.x + 40, canvas.y + frame.y + 40);
    expect(await view(page, 'view.selectedShape')).toBe(0);
    // Moved by 64 pixels right and 20 down.
    await page.mouse.move(canvas.x + frame.x + 40, canvas.y + frame.y + 40);
    await page.mouse.down();
    await page.mouse.move(canvas.x + frame.x + 70, canvas.y + frame.y + 50, { steps: 4 });
    await page.mouse.move(canvas.x + frame.x + 104, canvas.y + frame.y + 60, { steps: 4 });
    await page.mouse.up();
    await expect(live(page)).toHaveText('Shape moved');
    const moved = await frameOf(page);
    expect([Math.round(moved.x - frame.x), Math.round(moved.y - frame.y)]).toEqual([64, 20]);
    // Sized by the corner at the bottom right.
    frame = moved;
    await page.mouse.move(canvas.x + frame.x + frame.width, canvas.y + frame.y + frame.height);
    await page.mouse.down();
    await page.mouse.move(canvas.x + frame.x + frame.width + 20, canvas.y + frame.y + frame.height + 10, { steps: 4 });
    await page.mouse.move(canvas.x + frame.x + frame.width + 40, canvas.y + frame.y + frame.height + 20, { steps: 4 });
    await page.mouse.up();
    const sized = await frameOf(page);
    expect([Math.round(sized.width), Math.round(sized.height)]).toEqual([Math.round(frame.width + 40), Math.round(frame.height + 20)]);
    // Turned by the handle above the middle of the top side, to the right.
    const top = { x: canvas.x + sized.x + sized.width / 2, y: canvas.y + sized.y - 20 };
    await page.mouse.move(top.x, top.y);
    await page.mouse.down();
    await page.mouse.move(top.x + 100, canvas.y + sized.y + sized.height / 2 - 10, { steps: 4 });
    await page.mouse.move(top.x + 200, canvas.y + sized.y + sized.height / 2, { steps: 4 });
    await page.mouse.up();
    await expect(live(page)).toHaveText('Shape rotated');
    expect((await shapes(page))[0].rotation).toBeGreaterThan(60);
    await view(page, 'view.undo()');
    expect((await shapes(page))[0].rotation).toBeUndefined();
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    const back = await frameOf(page);
    expect([back.x, back.y, back.width, back.height].map(Math.round)).toEqual([start.x, start.y, start.width, start.height].map(Math.round));
  });

  test('the arrows move the selected shape, Delete deletes it, Escape gives the keys back to the cells', async ({ page }) => {
    await mount(page, await plainBook());
    await view(page, 'view.insertShape("ellipse", { at: { row: 2, col: 2 } })');
    const before = await frameOf(page);
    expect(await key(page, { key: 'ArrowRight' })).toBe(true);
    expect(await key(page, { key: 'ArrowDown', shiftKey: true })).toBe(true);
    const after = await frameOf(page);
    expect([Math.round(after.x - before.x), Math.round(after.y - before.y)]).toEqual([10, 1]);
    expect(await key(page, { key: 'Delete' })).toBe(true);
    await expect(live(page)).toHaveText('Shape deleted');
    expect(await shapes(page)).toEqual([]);
    await view(page, 'view.undo()');
    expect((await shapes(page)).length).toBe(1);
    await view(page, 'view.selectShape(0)');
    expect(await key(page, { key: 'Escape' })).toBe(true);
    expect(await view(page, 'view.selectedShape')).toBeUndefined();
  });

  test('a double click types the text of a shape in a field over it; Ctrl+Enter applies it as one step, Escape gives it up', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await plainBook());
    await view(page, 'view.insertShape("textBox", { at: { row: 1, col: 1 } })');
    const canvas = await canvasBox(page);
    const frame = await frameOf(page);
    await page.mouse.dblclick(canvas.x + frame.x + 30, canvas.y + frame.y + 30);
    const field = page.locator('#host .bym-shape-input');
    await expect(field).toBeFocused();
    await page.keyboard.type('Bir');
    await page.keyboard.press('Enter');
    await page.keyboard.type('İki <b>');
    await page.keyboard.press('Control+Enter');
    await expect(field).toHaveCount(0);
    expect((await shapes(page))[0].text).toBe('Bir\nİki <b>');
    // The text of a shape is drawn on the canvas, never put into the page as markup.
    expect(await page.locator('#host b').count()).toBe(0);
    await view(page, 'view.editShapeText(0)');
    await page.keyboard.type(' sonra');
    await page.keyboard.press('Escape');
    expect((await shapes(page))[0].text).toBe('Bir\nİki <b>');
    await view(page, 'view.undo()');
    expect((await shapes(page))[0].text).toBe('');
    // What is being typed is applied before the workbook is taken (as a save takes it): it goes into the file.
    await view(page, 'view.editShapeText(0)');
    await page.keyboard.type('Kayıtta');
    expect(await view(page, 'view.hasUnappliedText()')).toBe(true);
    expect(await view(page, 'view.commitPending()')).toBe(true);
    await mount(page, await saved(page));
    expect((await shapes(page))[0].text).toBe('Kayıtta');
  });

  test('the fill and text colour buttons and the size list change the selected shape; its line has a menu of its own', async ({ page }) => {
    await mount(page, await plainBook());
    await view(page, 'view.insertShape("rect", { at: { row: 1, col: 1 }, text: "Renk" })');
    // The cells keep their own look whatever is done to the shape: what they have now (no fill: a pattern of none).
    const cells = await view(page, 'JSON.stringify(view.selectionFormat.fill)');
    await command(page, 'fillColor').click();
    await popover(page).locator('.bym-pop-swatch[data-color="#FF0000"]').click();
    expect((await shapes(page))[0].fill).toBe('#FF0000');
    const frame = await frameOf(page);
    expect(await ink(page, RED, { x: frame.x + 6, y: frame.y + 6, width: 30, height: 10 })).toBeGreaterThan(200);
    await page.locator('#host .bym-tb-size').selectOption('18');
    expect((await shapes(page))[0].textSize).toBe(18);
    await command(page, 'insertShape').click();
    await popover(page).getByText('Line weight…').click();
    await expect(popover(page)).toBeVisible();
    await popover(page).getByText('3 pt').click();
    expect((await shapes(page))[0].outline.width).toBe(3);
    // The cells keep their own fill, and each change was one step of the shape.
    expect(await view(page, 'JSON.stringify(view.selectionFormat.fill)')).toBe(cells);
    await view(page, 'view.undo()');
    expect((await shapes(page))[0].outline.width).not.toBe(3);
    expect(await view(page, 'JSON.stringify(view.selectionFormat.fill)')).toBe(cells);
  });

  test('a shape is copied and pasted by the events of the clipboard, beside where it stood; the clipboard gets a word and a mark, never the text of the shape as markup', async ({ page }) => {
    await mount(page, await plainBook());
    await view(page, 'view.insertShape("roundRect", { at: { row: 1, col: 1 }, text: "<i>Kopya</i>" })');
    const put = await clipboard(page, 'copy');
    await expect(live(page)).toHaveText('Shape copied');
    expect(put.text).toBe('[Shape]');
    expect(put.html).toMatch(/^<span data-bym-shape="[a-z0-9]+">\[Shape\]<\/span>$/);
    await clipboard(page, 'paste', put);
    await expect(live(page)).toHaveText('Shape pasted');
    const list = await shapes(page);
    expect(list.length).toBe(2);
    expect(list[1].text).toBe('<i>Kopya</i>');
    expect(await view(page, 'view.selectedShape')).toBe(1);
    const first = await frameOf(page, 0);
    const second = await frameOf(page, 1);
    expect([Math.round(second.x - first.x), Math.round(second.y - first.y)]).toEqual([24, 24]);
    // A cut deletes it as one step; its paste brings it back.
    await clipboard(page, 'cut');
    await expect(live(page)).toHaveText('Shape cut');
    expect((await shapes(page)).length).toBe(1);
    await view(page, 'view.undo()');
    expect((await shapes(page)).length).toBe(2);
  });

  test('inside a frame of the file without a fill the cells are clicked and edited; its outline selects it', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    // A frame from B2 to F12, drawn around cells: no fill, a black outline.
    await mount(page, await pictureWorkbook({ drawing: twoCell([1, 1], [6, 12], sp({ props: '<a:noFill/>' + outline('000000') })) }));
    const canvas = await canvasBox(page);
    // The middle of D6: inside the frame.
    await page.mouse.click(canvas.x + HEADER_WIDTH + 3 * COLUMN_WIDTH + 30, canvas.y + HEADER_HEIGHT + 5 * ROW_HEIGHT + 10);
    expect(await view(page, 'view.selectedShape')).toBeUndefined();
    expect(await view(page, 'api.rangeName(view.selection.range)')).toBe('D6');
    // A double click there edits the cell, not the text of the frame.
    await page.mouse.dblclick(canvas.x + HEADER_WIDTH + 3 * COLUMN_WIDTH + 30, canvas.y + HEADER_HEIGHT + 5 * ROW_HEIGHT + 10);
    await expect(page.locator('#host .bym-shape-input')).toHaveCount(0);
    expect(await view(page, 'view.isEditing')).toBe(true);
    await page.keyboard.press('Escape');
    // On its left side: the frame.
    await page.mouse.click(canvas.x + HEADER_WIDTH + COLUMN_WIDTH + 1, canvas.y + HEADER_HEIGHT + 5 * ROW_HEIGHT + 10);
    expect(await view(page, 'view.selectedShape')).toBe(0);
  });

  test('a read-only view and a protected sheet take no shape: the button is off and says why', async ({ page }) => {
    await mount(page, await plainBook(), { readOnly: true });
    await expect(command(page, 'insertShape')).toBeDisabled();
    expect(await view(page, 'view.insertShape("rect")')).toBe(-1);
    await mount(page, await pictureWorkbook({ protection: '<sheetProtection sheet="1" objects="1"/>' }));
    await expect(command(page, 'insertShape')).toBeDisabled();
    await expect(command(page, 'insertShape')).toHaveAttribute('title', 'The sheet is protected: its shapes cannot be changed');
    await expect(page.evaluate(() => (window as any).__editor.view.insertShape('rect'))).rejects.toThrow(/protected/);
  });
});
